/// <summary>
/// MPJ_36274 - Post Packing Slip Registration
/// Parameter to include number of tasks.
/// </summary>
/// <param name = "_tasks">NumOfThreads</param>
/// <returns>Number of threads</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('@MET:CustCreditLimitTasks'),
    SysOperationDisplayOrderAttribute('1')
]
public int parmTasks(int _tasks = tasks)
{
    tasks = _tasks;
    return tasks;
}

/// <summary>
/// MPJ_36274 - Post Packing Slip Registration
/// </summary>
/// <param name = "_orderList">List of orders to process</param>
/// <returns>List of orders to process</returns>
[
    DataMemberAttribute('OrderList'),
    SysOperationControlVisibilityAttribute(false),
    AifCollectionTypeAttribute(identifierStr(_receiptList), Types::String)
]
public Set parmOrderList(Set _orderList = orderList)
{
    orderList = _orderList;
    return orderList;
}
